const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cfg=window.PULSO_CONFIG, demo=!cfg.supabaseUrl||!cfg.supabaseKey;
let db,user=null,profile={name:'',phone:'',avatar_url:'',role:'member'},page='agenda',filter='Todas',week=0,day=0,adminTab='classes',busy=false;
const images={Funcional:'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?auto=format&fit=crop&w=800&q=85',Spinning:'https://images.unsplash.com/photo-1534258936925-c58bed479fcb?auto=format&fit=crop&w=800&q=85',Yoga:'https://images.unsplash.com/photo-1544367567-0f2fcb009e0b?auto=format&fit=crop&w=800&q=85'};
const today=new Date();today.setHours(0,0,0,0);const monday=new Date(today);monday.setDate(today.getDate()-(today.getDay()+6)%7);day=(today.getDay()+6)%7;
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const selectedDate=()=>{let d=new Date(monday);d.setDate(d.getDate()+week*7+day);return d};
const nice=d=>new Date(d).toLocaleDateString('es-AR',{weekday:'long',day:'numeric',month:'long'});
function seed(){let a=[];for(let d=0;d<21;d++)for(let t=0;t<3;t++){let date=new Date(monday);date.setDate(date.getDate()+d);date.setHours([9,18,19][t],t===1?30:0);a.push({id:crypto.randomUUID(),title:['Funcional training','Spinning power','Yoga flow'][t],type:['Funcional','Spinning','Yoga'][t],teacher:['Martín López','Sofi García','Lucía Fernández'][t],starts_at:date.toISOString(),duration:[50,45,60][t],capacity:[20,16,15][t],occupied:[12,14,5][t],room:['Sala principal','Sala de cycling','Sala zen'][t]})}return a}
let classes=demo?JSON.parse(localStorage.getItem('pulso_classes')||'null')||seed():[], bookings=demo?JSON.parse(localStorage.getItem('pulso_bookings')||'[]'):[],members=[];
if(demo)profile=JSON.parse(localStorage.getItem('pulso_profile')||'null')||profile;
function persist(){if(demo){localStorage.setItem('pulso_classes',JSON.stringify(classes));localStorage.setItem('pulso_bookings',JSON.stringify(bookings));localStorage.setItem('pulso_profile',JSON.stringify(profile))}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
const isAdmin=()=>demo||profile.role==='admin';const own=id=>bookings.some(b=>b.class_id===id);
const free=c=>Math.max(0,c.capacity-(c.occupied||0));
function avatar(){return profile.avatar_url?`<img src="${esc(profile.avatar_url)}" alt="Tu foto">`:esc((profile.name||'P')[0].toUpperCase())}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.querySelector('[data-page="admin"]').hidden=!isAdmin();$('#demo').hidden=!demo;$('#book-count').textContent=bookings.length;$('#username').innerHTML=`${esc(profile.name||'Explorá PULSO')}<small>${user?'Socio del club':demo?'Experiencia de demostración':'Ingresar a mi cuenta'}</small>`;$('.user .avatar').innerHTML=avatar();$('#login').textContent=user?'Cerrar sesión ↗':'Ingresar ↗';if(page==='agenda')agenda();if(page==='bookings')myBookings();if(page==='profile')profileView();if(page==='admin')adminView()}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();window.scrollTo({top:0,behavior:'smooth'})});
function title(k,h,p){return `<div class="page-title"><div><div class="eyebrow">${k}</div><h1>${h}</h1><p>${p}</p></div><div class="date-label">◷ &nbsp; ${today.toLocaleDateString('es-AR',{day:'numeric',month:'long',year:'numeric'})}</div></div>`}
function card(c,showDate=false){let f=free(c),has=own(c.id),past=new Date(c.starts_at)<=new Date();return `<article class="card"><div class="card-image"><img src="${images[c.type]}" alt="Entrenamiento de ${esc(c.type)}" loading="lazy"><span class="badge ${c.type.toLowerCase()}">${esc(c.type).toUpperCase()}</span><span class="duration">◷ ${c.duration} min</span></div><div class="card-body">${showDate?`<div class="booking-date">${nice(c.starts_at)}</div>`:''}<div class="card-time"><span>◷ ${new Date(c.starts_at).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})} hs</span><span>${esc(c.room)}</span></div><h3>${esc(c.title)}</h3><div class="trainer"><span class="avatar">${esc(c.teacher[0])}</span>${esc(c.teacher)}</div><div class="capacity"><span>${c.occupied||0} / ${c.capacity} inscriptos</span><strong class="${f<=3?'low':''}">${has?'✓ Tenés tu lugar':f?`${f} lugares disponibles`:'Clase completa'}</strong></div><div class="bar"><i style="width:${Math.min(100,(c.occupied||0)/c.capacity*100)}%"></i></div><button class="primary ${has?'reserved':''}" data-reserve="${c.id}" ${(!has&&(!f||past))?'disabled':''}>${has?'✓ Reservado · Cancelar':past?'Clase finalizada':!f?'Sin lugares':'Reservar mi lugar &nbsp; ↗'}</button></div></article>`}
function bindReservations(){document.querySelectorAll('[data-reserve]').forEach(b=>b.onclick=()=>reserve(b.dataset.reserve))}
function agenda(){let date=selectedDate(),list=classes.filter(c=>dateKey(new Date(c.starts_at))===dateKey(date)&&(filter==='Todas'||filter===c.type)).sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));$('#view').innerHTML=title('HACÉ LUGAR PARA VOS',`Tu próximo movimiento${profile.name?', '+esc(profile.name.split(' ')[0]):''}.`,'Elegí tu clase, reservá tu lugar y vení a darlo todo.')+`<section class="hero"><img src="${images.Funcional}" alt="Atleta entrenando en el gimnasio"><div class="hero-copy"><div class="eyebrow">LA MEJOR VERSIÓN DE VOS</div><h2>Menos excusas.<br><em>Más movimiento.</em></h2><p>Una clase. Un paso más. Encontrá tu ritmo en PULSO.</p></div><div class="hero-tag">ESTO ES PULSO ↗</div></section><div class="summary"><div class="stat"><span class="stat-icon">▦</span><div><strong>${classes.filter(c=>{let diff=(new Date(c.starts_at)-monday)/86400000;return diff>=week*7&&diff<(week+1)*7}).length}</strong><small>Clases esta semana</small></div><span class="hint">A tu ritmo ↗</span></div><div class="stat"><span class="stat-icon">◷</span><div><strong>${bookings.length.toString().padStart(2,'0')}</strong><small>Mis clases reservadas</small></div><span class="hint">¡Vamos por más!</span></div><div class="stat"><span class="stat-icon">ϟ</span><div><strong>3</strong><small>Formas de moverte</small></div><span class="hint">Encontrá la tuya</span></div></div><section><div class="section-head"><h2>Encontrá tu próxima clase</h2><div class="week-control"><button class="arrow" id="prev" aria-label="Semana anterior">‹</button><span>${week===0?'Esta semana':nice(date).split(',').pop()}</span><button class="arrow" id="next" aria-label="Semana siguiente">›</button></div></div><div class="days">${Array.from({length:7},(_,i)=>{let d=new Date(monday);d.setDate(d.getDate()+week*7+i);return `<button class="day ${day===i?'selected':''}" data-day="${i}" aria-pressed="${day===i}"><span>${['LUN','MAR','MIÉ','JUE','VIE','SÁB','DOM'][i]}</span><strong>${d.getDate()}</strong><i></i></button>`}).join('')}</div><div class="filters">${['Todas','Funcional','Spinning','Yoga'].map(f=>`<button class="filter ${filter===f?'selected':''}" data-filter="${f}">${f==='Todas'?'Todas las clases':f}</button>`).join('')}</div><div class="results-title">${nice(date)}<span>${list.length} clases disponibles</span></div><div class="cards">${list.map(c=>card(c)).join('')||'<div class="empty"><h3>Hoy bajamos un cambio</h3>Probá con otro día o actividad.</div>'}</div></section>`;$('#prev').onclick=()=>{week--;agenda()};$('#next').onclick=()=>{week++;agenda()};document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{day=Number(b.dataset.day);agenda()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;agenda()});bindReservations()}
async function refresh(){if(demo)return;const results=await Promise.all([db.rpc('list_classes'),db.from('bookings').select('*'),db.from('profiles').select('*').eq('id',user.id).single()]);for(const r of results)if(r.error)throw r.error;classes=results[0].data;bookings=results[1].data.filter(b=>b.user_id===user.id);profile=results[2].data;if(isAdmin()){let r=await db.from('profiles').select('*').order('name');if(r.error)throw r.error;members=r.data}}
async function reserve(id){if(!demo&&!user)return auth();if(busy)return;let c=classes.find(c=>c.id===id),cancel=own(id);if(cancel){modal(`<h2>¿Liberás tu lugar?</h2><p>${esc(c.title)} · ${nice(c.starts_at)}. Otro socio va a poder aprovecharlo.</p><div class="modal-actions"><button class="primary" id="confirm-cancel">Sí, cancelar reserva</button><button class="secondary" id="keep">Me quedo</button></div>`);$('#keep').onclick=()=>$('#modal').close();$('#confirm-cancel').onclick=()=>mutateReservation(c,true);return}await mutateReservation(c,false)}
async function mutateReservation(c,cancel){busy=true;try{if(demo){if(cancel){bookings=bookings.filter(b=>b.class_id!==c.id);c.occupied--}else{if(free(c)<=0)throw Error('La clase se completó. Elegí otro horario.');bookings.push({class_id:c.id,user_id:'demo'});c.occupied++}persist()}else{let r=cancel?await db.from('bookings').delete().eq('class_id',c.id).eq('user_id',user.id):await db.rpc('book_class',{p_class_id:c.id});if(r.error)throw r.error;await refresh()}$('#modal').close();render();toast(cancel?'Reserva cancelada. ¡Nos vemos en la próxima!':'¡Tu lugar está reservado! Nos vemos en el club.')}catch(e){toast(e.message)}finally{busy=false}}
function myBookings(){let list=classes.filter(c=>own(c.id)).sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));$('#view').innerHTML=title('TU MOMENTO ESTÁ AGENDADO','Mis turnos','Todo lo que viene, en un solo lugar.')+`<div class="cards">${list.map(c=>card(c,true)).join('')||'<div class="empty"><h3>Tu próxima clase te está esperando</h3>Reservá desde la agenda y encontrá tus turnos acá.<p><button class="primary" id="go-agenda">Explorar clases ↗</button></p></div>'}</div>`;if($('#go-agenda'))$('#go-agenda').onclick=()=>{page='agenda';render()};bindReservations()}
function profileView(){if(!demo&&!user){$('#view').innerHTML=title('UN ESPACIO PARA VOS','Mi perfil','Ingresá para completar tus datos.')+'<button class="primary" id="profile-login">Ingresar</button>';$('#profile-login').onclick=()=>auth();return}$('#view').innerHTML=title('ASÍ TE CONOCEMOS','Mi perfil','Tus datos, siempre al día.')+`<div class="form-panel"><div class="profile-head"><span class="avatar">${avatar()}</span><div><h2>${esc(profile.name||'Tu perfil PULSO')}</h2><span>${esc(user?.email||'Socio de demostración')}</span></div></div><form id="profile-form"><label>Nombre completo<input name="name" required maxlength="100" value="${esc(profile.name)}" autocomplete="name"></label><label>Teléfono<input name="phone" type="tel" maxlength="30" value="${esc(profile.phone)}" autocomplete="tel"></label><label>Foto de perfil<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG o WebP. Máximo 2 MB.</small></label><div class="error" role="alert"></div><button class="primary">Guardar cambios ↗</button></form></div>`;$('#profile-form').onsubmit=async e=>{e.preventDefault();let f=e.target,b=f.querySelector('button');b.disabled=true;try{let photo=f.elements.namedItem('photo').files[0],url=profile.avatar_url;if(photo){if(photo.size>2*1024*1024||!['image/jpeg','image/png','image/webp'].includes(photo.type))throw Error('Elegí una imagen JPG, PNG o WebP de hasta 2 MB.');if(demo)url=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(photo)});else{let path=`${user.id}/${crypto.randomUUID()}.${photo.type.split('/')[1]}`;let r=await db.storage.from('avatars').upload(path,photo);if(r.error)throw r.error;url=db.storage.from('avatars').getPublicUrl(path).data.publicUrl}}let values={name:f.elements.namedItem('name').value.trim(),phone:f.elements.namedItem('phone').value.trim(),avatar_url:url};if(!values.name)throw Error('Ingresá tu nombre.');if(demo){Object.assign(profile,values);persist()}else{let r=await db.from('profiles').update(values).eq('id',user.id);if(r.error)throw r.error;await refresh()}render();toast('Perfil actualizado.')}catch(e){f.querySelector('.error').textContent=e.message}finally{b.disabled=false}}}
function auth(signup=false){if(demo){modal('<h2>Tu cuenta, en PULSO</h2><p>El registro y el ingreso estarán disponibles cuando conectemos el proyecto de Supabase. Mientras tanto, podés probar las reservas, tu perfil y la administración en modo demo.</p><button class="primary" id="continue-demo">Seguir explorando ↗</button>');$('#continue-demo').onclick=()=>$('#modal').close();return}modal(`<h2>${signup?'Sumate al movimiento':'Qué bueno verte'}</h2><p>${signup?'Creá tu cuenta y encontrá tu próxima clase.':'Ingresá y hacé lugar para vos.'}</p><form id="auth-form">${signup?'<label>Nombre<input name="name" required autocomplete="name" maxlength="100"></label>':''}<label>Email<input name="email" type="email" required autocomplete="email"></label><label>Contraseña<input name="password" type="password" required minlength="8" autocomplete="${signup?'new-password':'current-password'}"></label><div class="error" role="alert"></div><button class="primary">${signup?'Crear cuenta':'Ingresar'} ↗</button></form><button class="text-button switch-auth" id="switch-auth">${signup?'Ya tengo cuenta':'¿Primera vez? Creá tu cuenta'}</button>`);$('#switch-auth').onclick=()=>auth(!signup);$('#auth-form').onsubmit=async e=>{e.preventDefault();let f=e.target,b=f.querySelector('button');b.disabled=true;try{let r=signup?await db.auth.signUp({email:f.elements.namedItem('email').value,password:f.elements.namedItem('password').value,options:{data:{name:f.elements.namedItem('name').value.trim()}}}):await db.auth.signInWithPassword({email:f.elements.namedItem('email').value,password:f.elements.namedItem('password').value});if(r.error)throw r.error;if(!r.data.session){f.innerHTML='<p>Revisá tu correo y confirmá tu cuenta para ingresar.</p>';return}user=r.data.user;await refresh();$('#modal').close();render()}catch(e){f.querySelector('.error').textContent=e.message}finally{b.disabled=false}}}
$('#user').onclick=()=>user?(page='profile',render()):auth();$('#login').onclick=async()=>{if(!user)return auth();let r=await db.auth.signOut();if(r.error)return toast(r.error.message);user=null;profile={name:'',phone:'',avatar_url:'',role:'member'};bookings=[];classes=[];page='agenda';render()};
function adminView(){if(!isAdmin()){page='agenda';render();return}$('#view').innerHTML=title('EL CLUB EN TUS MANOS','Administración','Más organización. Más tiempo para tu comunidad.')+`${demo?'<div class="note">Panel de demostración. En Supabase, solo las cuentas con rol de dueño pueden acceder y modificar datos.</div>':''}<div class="section-head"><div class="tabs"><button class="filter ${adminTab==='classes'?'selected':''}" id="tab-classes">Clases (${classes.length})</button><button class="filter ${adminTab==='members'?'selected':''}" id="tab-members">Socios (${demo?1:members.length})</button></div><button class="primary" id="new-class">+ Nueva clase</button></div><div id="admin-list"></div>`;$('#tab-classes').onclick=()=>{adminTab='classes';adminView()};$('#tab-members').onclick=()=>{adminTab='members';adminView()};$('#new-class').onclick=()=>editClass();if(adminTab==='members'){$('#admin-list').innerHTML=(demo?[{...profile,name:profile.name||'Socio demo',email:'Datos de demostración'}]:members).map(m=>`<div class="admin-row"><span class="avatar">${esc((m.name||'S')[0])}</span><div class="details"><b>${esc(m.name||'Sin nombre')}</b><small>${esc(m.email)} · ${esc(m.phone||'Sin teléfono')}</small></div><span>${m.role==='admin'?'Dueño':'Socio'}</span></div>`).join('')||'<div class="empty">Todavía no hay socios registrados.</div>';return}$('#admin-list').innerHTML=[...classes].sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at)).map(c=>`<div class="admin-row"><div class="details"><b>${esc(c.title)}</b><small>${nice(c.starts_at)} · ${new Date(c.starts_at).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})} · ${esc(c.teacher)} · ${c.occupied}/${c.capacity} socios</small></div><div class="admin-actions"><button class="secondary" data-attendees="${c.id}">Inscriptos</button><button class="secondary" data-edit="${c.id}">Editar</button><button class="secondary" data-delete="${c.id}">Eliminar</button></div></div>`).join('')||'<div class="empty">Cargá la primera clase de tu club.</div>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editClass(classes.find(c=>c.id===b.dataset.edit)));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteClass(b.dataset.delete));document.querySelectorAll('[data-attendees]').forEach(b=>b.onclick=()=>attendees(b.dataset.attendees))}
function editClass(c){let date=c?new Date(c.starts_at):selectedDate();modal(`<h2>${c?'Editar':'Nueva'} clase</h2><p>Prepará el próximo encuentro.</p><form id="class-form"><label>Nombre de la clase<input name="title" required maxlength="100" value="${esc(c?.title||'')}"></label><div class="split"><label>Actividad<select name="type">${['Funcional','Spinning','Yoga'].map(t=>`<option ${c?.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Profe<input name="teacher" required maxlength="100" value="${esc(c?.teacher||'')}"></label></div><div class="split"><label>Día<input name="date" type="date" required value="${dateKey(date)}"></label><label>Hora<input name="time" type="time" required value="${c?date.toTimeString().slice(0,5):'18:00'}"></label></div><div class="split"><label>Cupos<input name="capacity" type="number" min="${Math.max(1,c?.occupied||0)}" max="500" required value="${c?.capacity||20}"></label><label>Duración (min)<input name="duration" type="number" min="10" max="240" required value="${c?.duration||50}"></label></div><label>Sala<input name="room" required maxlength="80" value="${esc(c?.room||'Sala principal')}"></label><div class="error" role="alert"></div><button class="primary">Guardar clase ↗</button></form>`);$('#class-form').onsubmit=async e=>{e.preventDefault();let f=e.target,b=f.querySelector('button');b.disabled=true;try{let values={title:f.elements.namedItem('title').value.trim(),type:f.elements.namedItem('type').value,teacher:f.elements.namedItem('teacher').value.trim(),starts_at:new Date(`${f.elements.namedItem('date').value}T${f.elements.namedItem('time').value}`).toISOString(),capacity:+f.elements.namedItem('capacity').value,duration:+f.elements.namedItem('duration').value,room:f.elements.namedItem('room').value.trim()};if(!values.title||!values.teacher||!values.room)throw Error('Completá todos los campos.');if(demo){if(c)Object.assign(c,values);else classes.push({...values,id:crypto.randomUUID(),occupied:0});persist()}else{let r=c?await db.from('classes').update(values).eq('id',c.id):await db.from('classes').insert(values);if(r.error)throw r.error;await refresh()}$('#modal').close();render();toast('Clase guardada.')}catch(e){f.querySelector('.error').textContent=e.message}finally{b.disabled=false}}}
function deleteClass(id){let c=classes.find(c=>c.id===id);modal(`<h2>¿Eliminar esta clase?</h2><p>${esc(c.title)}. Se cancelarán todas las reservas de esta clase.</p><button class="primary" id="confirm-delete">Eliminar clase</button>`);$('#confirm-delete').onclick=async e=>{e.target.disabled=true;try{if(demo){classes=classes.filter(c=>c.id!==id);bookings=bookings.filter(b=>b.class_id!==id);persist()}else{let r=await db.from('classes').delete().eq('id',id);if(r.error)throw r.error;await refresh()}$('#modal').close();render();toast('Clase eliminada.')}catch(e){toast(e.message)}}}
async function attendees(id){try{let people;if(demo)people=own(id)?[{name:profile.name||'Socio demo',email:'Tu reserva en este dispositivo'}]:[];else{let r=await db.from('bookings').select('user_id').eq('class_id',id);if(r.error)throw r.error;people=r.data.map(b=>members.find(m=>m.id===b.user_id)).filter(Boolean)}modal(`<h2>Quiénes se suman</h2><p>${esc(classes.find(c=>c.id===id).title)}</p>${people.map(p=>`<div class="admin-row"><div><b>${esc(p.name||'Sin nombre')}</b><small>${esc(p.email)}</small></div></div>`).join('')||'<div class="empty">Todavía no hay reservas de socios.</div>'}${demo?'<p>Los cupos de ejemplo no representan socios reales. Acá se muestran las reservas que hagas en la demo.</p>':''}`)}catch(e){toast(e.message)}}
async function init(){if(!demo){try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2');db=createClient(cfg.supabaseUrl,cfg.supabaseKey);let r=await db.auth.getSession();if(r.error)throw r.error;user=r.data.session?.user;if(user)await refresh();else{let r=await db.rpc('list_classes');if(r.error)throw r.error;classes=r.data}}catch(e){toast('No pudimos conectar: '+e.message)}}render()}
init();

